/* Called only after the owning executor stops command/job producers. Normal
 * stop appends a FIFO sentinel after all queued work. Terminal-fault cleanup
 * abandons queued callbacks but still joins every successfully started worker
 * before owner allocations can be reclaimed. A failed join retains the queues. */
int bioManagedStop(int abandon) {
    managed_bio_stopping = 1;
    for (bio_worker_data *bwd = bio_workers; bwd != bio_worker_end; ++bwd) {
        if (!bwd->bio_jobs) continue;
        if (abandon) {
            bio_job *job;
            while ((job = mutexQueuePop(bwd->bio_jobs, false)) != NULL)
                if (job != &managed_bio_stop) zfree(job);
            bwd->managed_stop_sent = 0;
        }
        if (bwd->managed_started && !bwd->managed_stop_sent) {
            mutexQueueAdd(bwd->bio_jobs, &managed_bio_stop);
            bwd->managed_stop_sent = 1;
        }
    }
    for (bio_worker_data *bwd = bio_workers; bwd != bio_worker_end; ++bwd) {
        if (bwd->managed_started) {
            if (pthread_join(bwd->bio_thread_id, NULL) != 0) return C_ERR;
            bwd->managed_started = 0;
        }
    }
    for (bio_worker_data *bwd = bio_workers; bwd != bio_worker_end; ++bwd) {
        if (!bwd->bio_jobs) continue;
        bio_job *job;
        while ((job = mutexQueuePop(bwd->bio_jobs, false)) != NULL)
            if (job != &managed_bio_stop) zfree(job);
        mutexQueueRelease(bwd->bio_jobs);
        bwd->bio_jobs = NULL;
    }
    return C_OK;
}
